static int powerpc_sha1_update ( struct shash_desc * desc , const u8 * data , unsigned int len ) { struct sha1_state * sctx = shash_desc_ctx ( desc ) ; unsigned int partial , done ; const u8 * src ; partial = sctx -> count & 0x3f ; sctx -> count += len ; done = 0 ; src = data ; if ( ( partial + len ) > 63 ) { if ( partial ) { done = - partial ; src = sctx -> buffer ; } { powerpc_sha_transform ( sctx -> state , src ) ; done += 64 ; src = data + done ; } done + 63 < len ; partial = 0 ; } memcpy ( sctx -> buffer + partial , src , len - done ) ; return 0 ; } 